<script setup lang="ts">import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {SlidersHorizontal,Search as SearchIcon} from 'lucide-vue-next';import {products,categories} from '../data';import ProductCard from '../components/ProductCard.vue';import PageHero from '../components/PageHero.vue';const props=defineProps<{mode:string}>();const route=useRoute();const q=ref('');const cat=ref((route.query.category as string)||'all');const sort=ref('featured');watch(()=>route.query.category,v=>cat.value=(v as string)||'all');const title=computed(()=>props.mode==='best'?'Best Sellers':props.mode==='seasonal'?'Seasonal Collection':props.mode==='gift'?'Gift Boxes':'Shop All');const subtitle=computed(()=>props.mode==='best'?'The One Bite favorites our customers order again and again.':props.mode==='seasonal'?'Limited-edition flavors inspired by the season.':props.mode==='gift'?'Thoughtful, beautiful and ready to make someone’s day.':'Discover cakes, pastries, sweets and gifts baked fresh in Kuwait.');const filtered=computed(()=>{let arr=[...products];if(props.mode==='best')arr=arr.filter(p=>p.best);if(props.mode==='seasonal')arr=arr.filter(p=>p.seasonal);if(props.mode==='gift')arr=arr.filter(p=>p.gift);if(cat.value!=='all')arr=arr.filter(p=>p.category===cat.value);if(q.value)arr=arr.filter(p=>(p.name+p.nameAr+p.description).toLowerCase().includes(q.value.toLowerCase()));if(sort.value==='low')arr.sort((a,b)=>a.price-b.price);if(sort.value==='high')arr.sort((a,b)=>b.price-a.price);if(sort.value==='rating')arr.sort((a,b)=>b.rating-a.rating);return arr});</script><template><PageHero eyebrow="One Bite Bakery" :title="title" :subtitle="subtitle"/><section class="section"><div class="container"><div class="filters"><div class="search-input"><SearchIcon :size="18"/><input v-model="q" placeholder="Search products..."></div><select v-model="cat"><option value="all">All categories</option><option v-for="c in categories" :value="c.id">{{c.name}}</option></select><select v-model="sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="rating">Highest rated</option></select><span class="result-count"><SlidersHorizontal :size="16"/> {{filtered.length}} products</span></div><div v-if="filtered.length" class="product-grid"><ProductCard v-for="p in filtered" :key="p.id" :product="p"/></div><div v-else class="empty"><h2>No products found</h2><p>Try a different search or category.</p></div></div></section></template>
